export function portLineColor(faction){return factionDefinition(faction)?.pennant_color??'#b6c8ce';}
export function portFactionGroups(ports){const groups=new Map();for(const port of ports){const definition=factionDefinition(port.faction),id=definition?.runtime_id??port.faction??'unknown';if(!groups.has(id))groups.set(id,{id,name:definition?.display_name??port.faction??'Unassigned',order:definition?.runtime_order??99,ports:[]});groups.get(id).ports.push(port);}return [...groups.values()].sort((a,b)=>a.order-b.order||a.name.localeCompare(b.name)).map(group=>({...group,ports:group.ports.sort((a,b)=>a.name.localeCompare(b.name)||a.id.localeCompare(b.id))}));}
