  this.legend=el('div');this.legend.className='economic-port-legend';const legendTools=el('div');legendTools.className='economic-legend-tools';for(const [label,hidden] of [['Show all ports',false],['Hide all ports',true]]){const b=el('button',label);b.onclick=()=>{this.hiddenPorts=new Set(hidden?(this.data?.ports??[]).map(p=>p.id):[]);this.renderLegend();this.draw();};legendTools.append(b);}
  const key=el('p','Lines: local stock-based reference price, colored by faction · Circles: deliveries · Triangles: pickups · Squares: internal allocations · Payments settle at acceptance; physical stocks update during handling. Actual payments are shown in event details. Hover for details.');key.className='economic-key';
  this.events=el('div');this.events.className='economic-events';this.dialog.append(heading,controls,this.status,this.chart,key,legendTools,this.legend,el('h3','Recent cargo movements'),this.events);document.body.append(this.dialog);
  this.button.onclick=()=>this.open();this.dialog.addEventListener('close',()=>{this.token++;this.pendingResource=null;clearInterval(this.timer);this.timer=null;this.tooltip.hidden=true;});this.dialog.addEventListener('keydown',e=>e.stopPropagation());
