  this.canvas.onpointermove=e=>{this.pointer={clientX:e.clientX,clientY:e.clientY};this.hover(e);};this.canvas.onpointerdown=this.canvas.onpointermove;this.canvas.onpointerleave=()=>{this.pointer=null;this.tooltip.hidden=true;};
