  this.canvas.width=width*dpr;this.canvas.height=height*dpr;const ctx=this.canvas.getContext('2d');if(!ctx)return;ctx.scale(dpr,dpr);ctx.fillStyle='#102c39';ctx.fillRect(0,0,width,height);const left=width<450?60:76,right=22,top=25,bottom=48,w=width-left-right,h=height-top-bottom;
  const visiblePoints=p=>{const points=p.points.filter(point=>point.time>=start);const prior=p.points.findLast(point=>point.time<start);return prior?[{...prior,time:start,eventId:null},...points]:points;};
  const lines=ports.map(p=>({port:p,points:visiblePoints(p).filter(point=>Number.isFinite(point.price)),color:portLineColor(p.faction)}));const values=lines.flatMap(line=>line.points.map(point=>point.price));let low=values.length?Math.min(...values):0,high=values.length?Math.max(...values):1;const spread=high-low,pad=spread>0?Math.max(.1,spread*.12):Math.max(.1,Math.abs(high)*.1);low=Math.max(0,low-pad);high+=pad;if(high<=low)high=low+1;const x=t=>left+(t-start)/(end-start)*w,y=p=>top+h-(p-low)/(high-low)*h;
  ctx.font='13px system-ui';ctx.lineWidth=1;for(let i=0;i<=4;i++){const value=low+(high-low)*i/4,py=y(value);ctx.strokeStyle='#46616b';ctx.beginPath();ctx.moveTo(left,py);ctx.lineTo(width-right,py);ctx.stroke();ctx.fillStyle='#dce7e8';ctx.textAlign='right';ctx.fillText(formatMoney(value),left-9,py+4);const t=start+(end-start)*i/4;ctx.textAlign=i===0?'left':i===4?'right':'center';ctx.fillText(elapsed(t),x(t),height-20);}
  ctx.textAlign='left';ctx.fillStyle='#abc6ce';ctx.fillText('Gold / unit',12,15);ctx.textAlign='right';ctx.fillText('Simulated time',width-right,height-4);
